import ULThemeLogo from "@/components/ULThemeLogo";
import ULThemeSubtitle from "@/components/ULThemeSubtitle";
import ULThemeTitle from "@/components/ULThemeTitle";

import { useLoginIdManager } from "../hooks/useLoginIdManager";

function Header() {
  const { texts, locales, product } = useLoginIdManager();

  // Check for premium theme from URL or product prop
  const devProduct =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("ext-product")
      : null;
  const isPremium = product === "premium" || devProduct === "premium";
  const isAtlas = product === "atlas-copco" || devProduct === "atlas-copco";

  // Use locale strings as fallback to SDK texts
  const logoAltText = texts?.logoAltText || locales?.heading?.logoAltText;

  return (
    <>
      <ULThemeLogo
        altText={logoAltText}
        className={isPremium ? "acul-float" : ""}
      />
      <ULThemeTitle className={isPremium ? "acul-golden-title" : isAtlas ? "acul-atlas-title" : ""}>
        {texts?.title || locales?.heading?.title}
      </ULThemeTitle>
      <ULThemeSubtitle className={isPremium ? "acul-golden-text opacity-80" : isAtlas ? "acul-atlas-subtitle" : ""}>
        {texts?.description || locales?.heading?.description}
      </ULThemeSubtitle>
    </>
  );
}

export default Header;
