import { useEffect, useMemo } from "react";
import ULThemeCard from "@/components/ULThemeCard";
import ULThemePageLayout from "@/components/ULThemePageLayout";
import ULThemeSeparator from "@/components/ULThemeSeparator";
import { useProductBrandingByName } from "@/hooks/useProductBranding";
import { extractTokenValue } from "@/utils/helpers/tokenUtils";
import { applyAuth0Theme } from "@/utils/theme/themeEngine";

import AlternativeLogins from "./components/AlternativeLogins";
import Footer from "./components/Footer";
import Header from "./components/Header";
import LoginIdForm from "./components/LoginIdForm";
import { useLoginIdManager } from "./hooks/useLoginIdManager";

// Floating particles for B2B2C consumer apps
function ConsumerParticles() {
  const particles = useMemo(
    () =>
      Array.from({ length: 20 }, (_, i) => ({
        id: i,
        left: `${Math.random() * 100}%`,
        delay: `${Math.random() * 8}s`,
        duration: `${10 + Math.random() * 10}s`,
        size: `${4 + Math.random() * 8}px`,
        opacity: 0.1 + Math.random() * 0.2,
      })),
    []
  );

  return (
    <div className="acul-consumer-particles">
      {particles.map((particle) => (
        <div
          key={particle.id}
          className="acul-consumer-particle"
          style={{
            left: particle.left,
            animationDelay: particle.delay,
            animationDuration: particle.duration,
            width: particle.size,
            height: particle.size,
            opacity: particle.opacity,
          }}
        />
      ))}
    </div>
  );
}

// Subtle grid pattern for B2B enterprise
function EnterpriseGrid() {
  return <div className="acul-enterprise-grid" />;
}

// Rewards badge for B2B2C
function RewardsBadge({ name }: { name: string }) {
  return (
    <div className="acul-rewards-badge">
      <span className="acul-rewards-icon">🎁</span>
      <span>{name}</span>
    </div>
  );
}

// Enterprise badge for B2B
function EnterpriseBadge({ name }: { name: string }) {
  return (
    <div className="acul-enterprise-badge">
      <span className="acul-enterprise-icon">🏢</span>
      <span>{name}</span>
    </div>
  );
}

// Security indicator for B2B
function SecurityIndicator() {
  return (
    <div className="acul-security-indicator">
      <div className="acul-security-dot" />
      <span>Secure Enterprise Login</span>
    </div>
  );
}

// Helper to detect product context and brand
function getProductContext(product: string | undefined): {
  isB2B: boolean;
  isB2B2C: boolean;
  displayName: string;
  brand: string;
} {
  if (!product) {
    return { isB2B: false, isB2B2C: false, displayName: "", brand: "" };
  }

  const b2bProducts: Record<string, { name: string; brand: string }> = {
    "acme-b2b": { name: "Acme Corp", brand: "acme" },
    "beta-b2b": { name: "Beta Inc", brand: "beta" },
    "gamma-b2b": { name: "Gamma Ltd", brand: "gamma" },
  };

  const b2b2cProducts: Record<string, { name: string; brand: string }> = {
    "acme-rewards": { name: "Acme Rewards", brand: "acme" },
    "beta-rewards": { name: "Beta Rewards", brand: "beta" },
    "gamma-rewards": { name: "Gamma Rewards", brand: "gamma" },
  };

  if (b2bProducts[product]) {
    return { isB2B: true, isB2B2C: false, displayName: b2bProducts[product].name, brand: b2bProducts[product].brand };
  }

  if (b2b2cProducts[product]) {
    return { isB2B: false, isB2B2C: true, displayName: b2b2cProducts[product].name, brand: b2b2cProducts[product].brand };
  }

  return { isB2B: false, isB2B2C: false, displayName: "", brand: "" };
}

function LoginIdScreen() {
  const {
    loginId,
    texts,
    locales,
    isPasskeyEnabled,
    alternateConnections,
    product,
  } = useLoginIdManager();

  // Get product from SDK or URL params (for dev testing)
  const devProduct =
    typeof window !== "undefined"
      ? new URLSearchParams(window.location.search).get("ext-product")
      : null;
  const activeProduct = product || devProduct || undefined;
  const productBranding = useProductBrandingByName(activeProduct);
  const { isB2B, isB2B2C, displayName, brand } = getProductContext(activeProduct);

  // Apply theme classes to body
  useEffect(() => {
    document.body.classList.remove(
      "acul-b2b-theme",
      "acul-b2b2c-theme",
      "acul-premium-theme",
      "acul-atlas-theme",
      "acul-brand-acme",
      "acul-brand-beta",
      "acul-brand-gamma"
    );

    if (isB2B) {
      document.body.classList.add("acul-b2b-theme");
      if (brand) {
        document.body.classList.add(`acul-brand-${brand}`);
      }
    } else if (isB2B2C) {
      document.body.classList.add("acul-b2b2c-theme");
      if (brand) {
        document.body.classList.add(`acul-brand-${brand}`);
      }
    }

    return () => {
      document.body.classList.remove(
        "acul-b2b-theme",
        "acul-b2b2c-theme",
        "acul-brand-acme",
        "acul-brand-beta",
        "acul-brand-gamma"
      );
    };
  }, [isB2B, isB2B2C, brand]);

  const showSeparator =
    isPasskeyEnabled ||
    (alternateConnections && alternateConnections.length > 0);

  const separatorText = texts?.separatorText || locales?.page?.orText;
  document.title = texts?.pageTitle || locales?.page?.title;

  applyAuth0Theme(loginId, productBranding);

  const socialLoginAlignment = extractTokenValue(
    "--ul-theme-widget-social-buttons-layout"
  );

  const renderSocialLogins = (alignment: "top" | "bottom") => (
    <>
      {alignment === "bottom" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
      <AlternativeLogins />
      {alignment === "top" && showSeparator && (
        <ULThemeSeparator text={separatorText} />
      )}
    </>
  );

  return (
    <ULThemePageLayout className="theme-universal">
      {/* B2B Enterprise background */}
      {isB2B && (
        <>
          <EnterpriseGrid />
          <SecurityIndicator />
        </>
      )}

      {/* B2B2C Consumer background */}
      {isB2B2C && <ConsumerParticles />}

      <ULThemeCard
        className={`w-full max-w-[400px] gap-0 ${isB2B ? "acul-b2b-card" : ""} ${isB2B2C ? "acul-b2b2c-card" : ""}`}
      >
        {/* B2B badge */}
        {isB2B && displayName && (
          <div className="flex justify-center pt-4">
            <EnterpriseBadge name={displayName} />
          </div>
        )}

        {/* B2B2C badge */}
        {isB2B2C && displayName && (
          <div className="flex justify-center pt-4">
            <RewardsBadge name={displayName} />
          </div>
        )}

        <Header />
        {socialLoginAlignment === "top" && renderSocialLogins("top")}
        <LoginIdForm />
        <Footer />
        {socialLoginAlignment === "bottom" && renderSocialLogins("bottom")}

        {/* B2B2C friendly messaging */}
        {isB2B2C && (
          <div className="acul-b2b2c-footer">
            <p>Earn points with every purchase</p>
          </div>
        )}
      </ULThemeCard>
    </ULThemePageLayout>
  );
}

export default LoginIdScreen;
